        doors=[{'name': 'd', 'p1': [150, 18], 'p2': [250, 18]}],
    ), 'b')
    level = _level(building)
    [(i, j, _)] = level['doors']
    assert {_xy(level, i)[1], _xy(level, j)[1]} == {pytest.approx(0.0)}


